from typing import List

def maxScore(nums: List[int]) -> int:
    def get_gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def get_lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // get_gcd(a, b)

    def calculate_score(arr):
        if not arr:
            return 0
        res_gcd = arr[0]
        res_lcm = arr[0]
        for i in range(1, len(arr)):
            res_gcd = get_gcd(res_gcd, arr[i])
            res_lcm = get_lcm(res_lcm, arr[i])
        return res_gcd * res_lcm

    n = len(nums)
    if n == 0:
        return 0
    if n == 1:
        return nums[0] * nums[0]

    # Initial score with no removals
    max_score = calculate_score(nums)

    # Try removing each element one by one
    for i in range(n):
        current_arr = nums[:i] + nums[i+1:]
        if not current_arr:
            continue
        max_score = max(max_score, calculate_score(current_arr))

    return max_score
