from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m = len(coins)
    n = len(coins[0])

    # dp[k][i][j] 表示到達 (i, j) 且使用了 k 次中和能力的最大收益
    # 使用 -float('inf') 初始化，因為收益可能為負數
    dp = [[[-float('inf')] * n for _ in range(m)] for _ in range(3)]

    # 初始化起點 (0, 0)
    val = coins[0][0]
    if val >= 0:
        dp[0][0][0] = val
    else:
        dp[0][0][0] = val  # 不使用能力，被搶走
        dp[1][0][0] = 0     # 使用一次能力，不被搶
        # 注意：如果 m=1, n=1且 coins[0][0]<0，dp[2] 也可視為用兩次（雖然沒意義）
        if m > 1 or n > 1: # 防止某些極端情況下的邏輯錯誤
             pass 

    # 如果起點是負數但我們想用能力中和它，其實在 dp[1][0][0] 已經處理了
    # 但為了保險，如果 coins[0][0] < 0，dp[2][0][0] 在邏輯上也可以是 0 (用兩次能力)
    if val < 0:
        dp[1][0][0] = max(dp[1][0][0], 0)
        dp[2][0][0] = max(dp[2][0][0], 0)

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            current_val = coins[i][j]
            is_negative = current_val < 0
            abs_val = abs(current_val) if is_negative else current_val

            for k in range(3):
                # 從上方或左方過來
                res = -float('inf')
                if i > 0:
                    res = max(res, dp[k][i-1][j])
                if j > 0:
                    res = max(res, dp[k][i][j-1])

                # 如果當前格子是正數或 0，直接加進去 (不消耗能力)
                if not is_negative:
                    dp[k][i][j] = max(dp[k][i][j], res + current_val)
                else:
                    # 選項 A: 不使用能力（被搶）
                    dp[k][i][j] = max(dp[k][i][j], res - abs_val)

                    # 選項 B: 使用一次能力 (如果 k > 0，從狀態 k-1 過來)
                    if k > 0:
                        prev_res = -float('inf')
                        if i > 0: prev_res = max(prev_res, dp[k-1][i-1][j])
                        if j > 0: prev_res = max(prev_res, dp[k-1][i][j-1])
                        dp[k][i][j] = max(dp[k][i][j], prev_res)

    return max(dp[k][m-1][n-1] for k in range(3))
